import{_ as t}from"./chunks/CreateLoginPage.B2-9vp7z.js";import{_ as a,c as r,a2 as o,o as s}from"./chunks/framework.CoXjB5sU.js";const i="/assets/CreateMain.BPTkCSpc.png",n="/assets/CreateMainPageFrames.Bl2j3_0c.png",l="/assets/CreateNavigationTabs.BGu-kT1D.png",h="/assets/CreateUserMenu.CwlsowK2.png",c="/assets/CreateNavigationTreeElements.qhWpwXhV.png",p="/assets/CreateNavigationTreeContextMenu.DewV4W29.png",d="/assets/CreateSearchForm.IpqAiF5_.png",m="/assets/CreateItemAction3DStructure.zcFlLvlf.png",u="/assets/CreateItemActionViewResults.COE93N0s.png",g="/assets/CreateItemActionDownload.JcOvVeMw.png",f="/assets/CreateItemActionRaw.DvkGeksp.png",w="/assets/CreateItemDetailsForm.Dx7IUGza.png",x=JSON.parse('{"title":"Create module walkthrough","description":"","frontmatter":{},"headers":[],"relativePath":"doc/guides/usage/create-module-walkthrough.md","filePath":"doc/guides/usage/create-module-walkthrough.md"}'),b={name:"doc/guides/usage/create-module-walkthrough.md"};function y(k,e,v,C,S,T){return s(),r("div",null,e[0]||(e[0]=[o('<h1 id="create-module-walkthrough" tabindex="-1">Create module walkthrough <a class="header-anchor" href="#create-module-walkthrough" aria-label="Permalink to &quot;Create module walkthrough&quot;">​</a></h1><p>The Create module is a single-page web application aimed at managing input and output files from computational chemistry research work, and to generate derived content from it. Create allows uploading, organizing, visualizing and curating your data, and sharing it with your project mates.</p><p><img src="'+i+'" alt="Create module main page"></p><h2 id="logging-in" tabindex="-1">Logging in <a class="header-anchor" href="#logging-in" aria-label="Permalink to &quot;Logging in&quot;">​</a></h2><p>Create and Browse share a centralized sign-on service: when you open <code>/create</code> you are redirected to the ioChem-BD login page, and after a successful login you can move between both modules without signing in again. Use the <strong>Log out</strong> option in the user menu (described below) to end your session for the whole platform.</p><p><img src="'+t+'" alt="ioChem-BD login page"></p><h2 id="the-main-window" tabindex="-1">The main window <a class="header-anchor" href="#the-main-window" aria-label="Permalink to &quot;The main window&quot;">​</a></h2><p>The window is composed of three frames:</p><ol><li>The <strong>main frame</strong>, with the operating modes as tabs: <strong>My workspace</strong>, <strong>Collaborate</strong>, <strong>Supervise</strong>, <strong>Search</strong> and <strong>Reports</strong></li><li>The <strong>Item Actions</strong> frame, showing the available views of the selected element</li><li>The <strong>Item Details</strong> frame, showing the administrative metadata of the selected element</li></ol><p><img src="'+n+'" alt="Frame composition"></p><p><img src="'+l+'" alt="Main frame mode tabs"></p><p>The <strong>Supervise</strong> tab only appears if you are a supervisor of other user accounts; the remaining tabs are always available.</p><p>The default operation flow within the Create module starts by navigating your uploaded content in the <strong>My workspace</strong> tab and selecting one element to display its content. When any element is selected, both the <em>Item Actions</em> frame and the <em>Item Details</em> frame refresh and display additional data.</p><p>Multiple element selection is allowed; it is normally associated with global operations, such as publishing a project or generating reports. Multiple element selection disables the <em>Item Actions</em> and <em>Item Details</em> frames. The selection counter next to the <strong>Refresh</strong> button shows how many elements are currently selected.</p><h2 id="the-top-bar-and-user-menu" tabindex="-1">The top bar and user menu <a class="header-anchor" href="#the-top-bar-and-user-menu" aria-label="Permalink to &quot;The top bar and user menu&quot;">​</a></h2><p>The bar on top of the window gives access to your account and to the Browse module:</p><ul><li>The <strong>Browse</strong> shortcut on the right opens the Browse module in the same session.</li><li>The user icon opens a dropdown with your account name and e-mail, and these options: <strong>Edit profile</strong> (your Browse profile), <strong>Download shell client</strong>, <strong>REST API</strong>, <strong>Help</strong> and <strong>Report bug</strong>, plus the <strong>Log out</strong> button.</li></ul><p><img src="'+h+'" alt="User dropdown menu"></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The <strong>Download shell client</strong> option generates a personal shell client package, preconfigured with your account details, that you can use to upload calculations from Linux terminals. Read more at <a href="./uploading-content-to-create/using-shell-client.html">Using the shell client</a>.</p></div><h2 id="my-workspace-tab" tabindex="-1">My workspace tab <a class="header-anchor" href="#my-workspace-tab" aria-label="Permalink to &quot;My workspace tab&quot;">​</a></h2><p>This tab is the entry point of all managing functionalities of the Create module. It displays a navigation tree composed of nodes and leaves: your <em>workspace</em>.</p><p><img src="'+c+'" alt="Project and calculation navigation tree"></p><p>Each node represents what we call a <strong>project</strong>. This is just a container element, like a folder, and can contain other subprojects or a set of single calculations, which are the basic elements of your data.</p><p>A <strong>calculation</strong> usually contains input files, CML converted output files, additional files, etc. The <em>My workspace</em> tab is the place to gather projects and calculations and organize your data sets the way you want to eventually publish them.</p><p>Above the tree, the toolbar provides a <strong>Refresh</strong> button, the selection counter and a <strong>Type to filter</strong> box that hides tree rows not matching the typed text.</p><h3 id="tree-columns" tabindex="-1">Tree columns <a class="header-anchor" href="#tree-columns" aria-label="Permalink to &quot;Tree columns&quot;">​</a></h3><ul><li><em>Name</em>: Element name (projects, calculations and reports).</li><li><em>Type</em>: Element type code, see the table below. Projects are labeled as <em>PRO</em>.</li><li><em>Shared</em>: Indicates that the element is shared with other users.</li><li><em>Handle</em>: Unique identifier of each published element, which can be accessed from the Browse module (see <a href="./publishing-calculations/publish-process.html">Publish data to Browse</a>).</li><li><em>Creation Date</em>: When the element was added to Create.</li><li><em>Edit</em>: Shortcut to edit elements that are already published in the Browse module.</li></ul><p>On calculations, the <em>Type</em> column contains the abbreviation of the original software package used:</p><table tabindex="0"><thead><tr><th>Code</th><th>Software package</th></tr></thead><tbody><tr><td>ADF</td><td><a href="https://www.scm.com/" target="_blank" rel="noreferrer">ADF</a></td></tr><tr><td>AMS</td><td><a href="https://www.scm.com/" target="_blank" rel="noreferrer">Amsterdam Modeling Suite</a></td></tr><tr><td>AMB</td><td><a href="http://ambermd.org/" target="_blank" rel="noreferrer">Amber</a></td></tr><tr><td>CAS</td><td><a href="http://www.castep.org/" target="_blank" rel="noreferrer">CASTEP</a></td></tr><tr><td>CP2</td><td><a href="https://www.cp2k.org/" target="_blank" rel="noreferrer">CP2K</a></td></tr><tr><td>GAU</td><td><a href="http://www.gaussian.com/" target="_blank" rel="noreferrer">Gaussian</a></td></tr><tr><td>GMC</td><td><a href="http://www.gromacs.org/" target="_blank" rel="noreferrer">GROMACS</a></td></tr><tr><td>GRO</td><td><a href="http://gronor.org/" target="_blank" rel="noreferrer">GronOR</a></td></tr><tr><td>GRRM</td><td><a href="https://iqce.jp/GRRM/index_e.shtml" target="_blank" rel="noreferrer">GRRM</a></td></tr><tr><td>LAM</td><td><a href="https://www.lammps.org" target="_blank" rel="noreferrer">LAMMPS</a></td></tr><tr><td>MOL</td><td><a href="https://molcas.org/" target="_blank" rel="noreferrer">Molcas</a></td></tr><tr><td>MOP</td><td><a href="http://openmopac.net/" target="_blank" rel="noreferrer">Mopac</a></td></tr><tr><td>ORC</td><td><a href="https://orcaforum.kofo.mpg.de/app.php/portal" target="_blank" rel="noreferrer">Orca</a></td></tr><tr><td>QEX</td><td><a href="https://www.quantum-espresso.org" target="_blank" rel="noreferrer">Quantum ESPRESSO</a></td></tr><tr><td>SIE</td><td><a href="https://siesta-project.org/siesta/" target="_blank" rel="noreferrer">SIESTA</a></td></tr><tr><td>TML</td><td><a href="http://www.turbomole.com/" target="_blank" rel="noreferrer">Turbomole</a></td></tr><tr><td>UMA</td><td><a href="https://www.scm.com/" target="_blank" rel="noreferrer">UMA universal machine-learning potentials</a></td></tr><tr><td>VSP</td><td><a href="https://www.vasp.at/" target="_blank" rel="noreferrer">Vienna Ab initio Simulation Package</a></td></tr><tr><td>XTB</td><td><a href="https://xtb-docs.readthedocs.io/" target="_blank" rel="noreferrer">xTB</a></td></tr></tbody></table><p>This list grows as more calculation types are implemented; check the <a href="/data/feature-matrix-table.html">Feature matrix</a> for the current coverage.</p><p>Elements of type <strong>REP</strong> are reports generated inside Create, such as supporting information documents or reaction energy profiles; read the <a href="./generating-reports.html">Generating reports</a> page to learn how to create them.</p><h3 id="context-menu" tabindex="-1">Context menu <a class="header-anchor" href="#context-menu" aria-label="Permalink to &quot;Context menu&quot;">​</a></h3><p>A context menu helps you with repetitive actions. Select any element in the workspace with a left click and then right click on it to see the available options:</p><ul><li><strong>Expand all / Collapse all</strong>: Open or close the whole subtree.</li><li><strong>Search from here...</strong>: Opens the Search tab with the element path as starting point.</li><li><strong>Select child elements</strong>: Adds all child elements of the element to the current selection.</li><li><strong>Share</strong>: Opens the share dialog for the selected project.</li><li><strong>New asset...</strong>: Uploads a new asset (project documents, RMMD, JSON data) attached to the selected project.</li><li><strong>Browse module → Publish</strong>: Starts the publication of the selected elements to the Browse module.</li><li><strong>Generate report</strong>: Creates a <em>Supporting Information</em>, <em>Reaction Energy Profile</em> or <em>Reaction Graph</em> report from the selected calculations.</li></ul><p><img src="'+p+'" alt="Element context menu"></p><p>Read the <a href="./publishing-calculations/publish-process.html">Publish data to Browse</a> section or the <a href="./generating-reports.html">Generating reports</a> section to learn how to proceed further.</p><h2 id="collaborate-tab" tabindex="-1">Collaborate tab <a class="header-anchor" href="#collaborate-tab" aria-label="Permalink to &quot;Collaborate tab&quot;">​</a></h2><p>The <strong>Collaborate</strong> tab displays all projects that other users have shared with you, enabling teamwork on computational chemistry research.</p><p>Working with shared projects is similar to working with your own projects: select any shared element to display its content in the <em>Item Actions</em> and <em>Item Details</em> frames. Depending on your permissions you can view, modify or even publish shared content.</p><p>For detailed information about sharing projects and managing permissions, please refer to the <a href="./collaborate-feature.html">Collaborate feature</a> documentation.</p><h2 id="supervise-tab" tabindex="-1">Supervise tab <a class="header-anchor" href="#supervise-tab" aria-label="Permalink to &quot;Supervise tab&quot;">​</a></h2><p>The <strong>Supervise</strong> tab appears for supervisor accounts and displays the workspaces of supervised users as a separate tree, so supervisors can organize, curate and publish data on behalf of their research group members.</p><p>Refer to the <a href="./supervise-feature.html">Supervise users</a> documentation for the complete workflow.</p><h2 id="search-tab" tabindex="-1">Search tab <a class="header-anchor" href="#search-tab" aria-label="Permalink to &quot;Search tab&quot;">​</a></h2><p>The <strong>Search</strong> tab displays a form where you can query all uploaded projects and calculations. Multiple filters are available:</p><ul><li><p><em>Type</em>: Search for <strong>Project</strong> or <strong>Calculation</strong> elements.</p></li><li><p><em>Calculation type</em>: Restrict results to one software package.</p></li><li><p><em>Name</em> and <em>Description</em>: Partial text or regular expression matching.</p></li><li><p><em>Geometry</em>: Search by chemical structure using a SMILES, InChI or InChIKey formula, with three matching modes:</p><ul><li><strong>Contains</strong>: The query structure appears anywhere in the molecule.</li><li><strong>Exact</strong>: The molecule matches the query formula exactly.</li><li><strong>Similar</strong>: Molecules similar to the query one.</li></ul><p>The <strong>Draw</strong> button opens a molecular structure editor to draw the query molecule.</p></li><li><p><em>Elements</em>: Pick chemical elements from a periodic table that must be present in the molecule.</p></li><li><p><em>Path</em>: Starting path to search for, see <a href="./uploading-content-to-create/using-web-interface.html#paths">path definition</a>.</p></li><li><p><em>Owner</em> and <em>Group</em>: Who created the element and which group owns it.</p></li><li><p><em>Creation dates</em>: Elements created between two dates.</p></li></ul><p><img src="'+d+'" alt="Multiple field search form"></p><p>After setting the search parameters you want, click the <strong>Search</strong> button to perform the query. The list of results replaces the form; click any listed element to display its particular <em>Item Actions</em> and <em>Item Details</em>. To perform a new query, press <strong>New search</strong> to go back to the form.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Enriching the <em>Description</em> field with meaningful information will allow you to look for those concepts when performing a search.</p></div><h2 id="reports-tab" tabindex="-1">Reports tab <a class="header-anchor" href="#reports-tab" aria-label="Permalink to &quot;Reports tab&quot;">​</a></h2><p>This tab activates advanced operations to process sets of calculations and generate reports. This mode is fully described in the <a href="./generating-reports.html">Generating reports</a> page.</p><h2 id="item-actions-frame" tabindex="-1">Item Actions frame <a class="header-anchor" href="#item-actions-frame" aria-label="Permalink to &quot;Item Actions frame&quot;">​</a></h2><p>This frame displays all views available for the element selected in the <em>My workspace</em> or <em>Search</em> trees. Before any selection it shows the <a href="./../other-operations/customizing-system-interface.html#welcome-panel">welcome panel</a>. Projects show the <em>Calculation upload</em> and <em>Asset upload</em> forms (see <a href="./uploading-content-to-create/using-web-interface.html">Using the web interface</a>), and calculations expose the following views, accessible as tabs:</p><ul><li><a href="#d-structure">3D structure</a></li><li><a href="#view-results">View results</a></li><li><a href="#download">Download</a></li><li><a href="#raw-view">RAW CML</a></li></ul><h3 id="_3d-structure" tabindex="-1">3D structure <a class="header-anchor" href="#_3d-structure" aria-label="Permalink to &quot;3D structure&quot;">​</a></h3><p>This view displays the molecular structure or simulation cell using JSmol (the JavaScript version of Jmol). In the case of geometry optimization runs, it shows the final geometry.</p><p><img src="'+m+'" alt="JSmol molecule visualization"></p><p>Calculations that include Molden files add two extra tabs inside this view:</p><ul><li><strong>Geometry</strong>: Displays every geometry step available in the calculation, one file per optimization step.</li><li><strong>Orbitals</strong>: Visualizes molecular orbitals rendered from the Molden file.</li></ul><p>Common JSmol operations:</p><ul><li>Hold left click + drag: Rotate molecule.</li><li>Central button scroll: Zoom in / out.</li><li>Hold Shift + double click + drag: Translate molecule.</li><li>Right click: Display the JSmol options menu.</li></ul><h3 id="view-results" tabindex="-1">View results <a class="header-anchor" href="#view-results" aria-label="Permalink to &quot;View results&quot;">​</a></h3><p>Some results of the output file uploaded to ioChem-BD are translated into CML (Chemical Markup Language), an XML language oriented to chemistry. Such markup language allows easy further conversion into any existing format, such as an HTML5 report, a PDF file or a JSON file.</p><p>Selected data is visualized, normally organized by content:</p><ul><li><em>General info</em>: Calculation administrative and descriptive metadata such as user name, calculation type or methods used.</li><li><em>Settings</em>: (VASP only) most relevant INCAR settings.</li><li><em>Atom info</em>: Atom type, coordinates and basis used. Eventually cell parameters, lattice vectors and atom valence.</li><li><em>Molecular info</em>: Implicit solvation parameters, charge and multiplicity.</li><li><em>Job</em>: Its content varies depending on the quantum chemistry package used to generate the calculation. For calculations with multiple jobs this section appears more than once.</li></ul><p>There is an exhaustive description of which fields are captured and how they are visualized in the <a href="/data/conversion-howto.html">From Codes to HTML5 report</a> section of the Data model documentation.</p><p><img src="'+u+'" alt="HTML report"></p><h3 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Download&quot;">​</a></h3><p>This view allows downloading the calculation files to your local filesystem.</p><p><img src="'+g+'" alt="Download files form"></p><h3 id="raw-view" tabindex="-1">RAW view <a class="header-anchor" href="#raw-view" aria-label="Permalink to &quot;RAW view&quot;">​</a></h3><p>This view displays the content of the calculation files inside a text area, one tab per file. On large files, it starts to download the file instead of displaying it.</p><p><img src="'+f+'" alt="View original files form"></p><h2 id="item-details-frame" tabindex="-1">Item Details frame <a class="header-anchor" href="#item-details-frame" aria-label="Permalink to &quot;Item Details frame&quot;">​</a></h2><p>Any project or calculation selected in the workspace immediately refreshes this form, displaying its administrative metadata. Some fields are modifiable, e.g. name, description, concept group, owner group and assigned permissions. Others are fixed, like the path, the owner user or the creation date.</p><p>In the lower area of this frame four buttons provide important actions:</p><ul><li><strong>Create Project</strong>: Generates a project in the current path using the values in the form.</li><li><strong>Modify</strong>: Replaces stored values for the selected element with the values in the form.</li><li><strong>Remove</strong>: Deletes the selected element.</li><li><strong>Share</strong>: Opens the sharing dialog to share the selected project with other users.</li></ul><p><img src="'+w+'" alt="Item details frame with operation buttons"></p><h3 id="upload-bar" tabindex="-1">Upload bar <a class="header-anchor" href="#upload-bar" aria-label="Permalink to &quot;Upload bar&quot;">​</a></h3><p>While uploading calculations via the web interface, a progress bar appears at the bottom of this frame, showing the progress of the uploading step. The <a href="./uploading-content-to-create/using-web-interface.html">Using the web interface</a> page describes the upload procedure in detail.</p>',80)]))}const q=a(b,[["render",y]]);export{x as __pageData,q as default};
